function resourceConsistency(value: any, ctx: z.RefinementCtx): void {
  for (const [alias, panel] of Object.entries(value.panels) as [string, any][]) {
    const rows = panel.data?.rows ?? [];
    if (panel.coverage.returned_count !== rows.length || panel.coverage.has_more !== panel.coverage.truncated)
      ctx.addIssue({code: z.ZodIssueCode.custom, message: "RESOURCE_PANEL_COVERAGE_INCONSISTENT", path: ["panels", alias, "coverage"]});
    if (value.data[alias] && JSON.stringify(value.data[alias]) !== JSON.stringify(rows))
      ctx.addIssue({code: z.ZodIssueCode.custom, message: "RESOURCE_PANEL_DATA_INCONSISTENT", path: ["data", alias]});
  }
  if (Buffer.byteLength(JSON.stringify(value), "utf8") > 1048576)
    ctx.addIssue({code: z.ZodIssueCode.custom, message: "RESOURCE_RESPONSE_BYTE_BOUND"});
}
